ee:message.ee:set-payload:
%dw 2.0
input payload multipart/form-data
output application/json
import * from dw::core::Strings
---
do {
    var fileDisposition = payload.parts.file.headers.'content-disposition' default ""
    var fileName = lower(fileDisposition as String)
    var fileContent = payload.parts.file.content
    var contentType = lower(payload.parts.file.headers.'Content-Type' default "" as String)
    var isExcel = (fileName contains ".xlsx") or (fileName contains ".xls") or (contentType contains "spreadsheet") or (contentType contains "excel")
    var isCsv = (fileName contains ".csv") or (contentType contains "csv")
    ---
    // Check if it's Excel file
    if (isExcel)
        do {
            // Excel is already parsed as an Object with sheet names as keys
            var allSheets = fileContent
            // Get the first sheet (usually "Sheet1" or similar)
            var sheetNames = namesOf(allSheets)
            var firstSheetName = sheetNames[0]
            var firstSheet = allSheets[firstSheetName]
            ---
            if (isEmpty(firstSheet))
                [{ status: "ERROR", message: "Excel file is empty" }]
            else
                firstSheet map (row) -> {
                    source_id: row.id as Number,
                    name: row.name default "UNKNOWN",
                    email: row.email default "noemail@example.com",
                    age: row.age as Number default 0
                }
        }
    // Check if it's CSV file
    else if (isCsv)
        do {
            var csvContent = fileContent
            ---
            if (isEmpty(csvContent))
                [{ status: "ERROR", message: "CSV file is empty" }]
            else
                csvContent map (row) -> {
                    source_id: row.id as Number,
                    name: row.name default "UNKNOWN",
                    email: row.email default "noemail@example.com",
                    age: row.age as Number default 0
                }
        }
    // Unsupported file type
    else
        [{ status: "ERROR", message: "Unsupported file type. Please upload CSV or Excel (.xlsx, .xls) files only." }]
}
